class ParserError(Exception):
    pass


def peek(word_list):
    return word_list[0][0] if word_list else None


def match(word_list, expected):
    if word_list and word_list[0][0] == expected:
        return word_list.pop(0)
    return None


def skip(word_list, word_type):
    while peek(word_list) == word_type:
        match(word_list, word_type)


def parse_verb(word_list):
    skip(word_list, "stop")
    if peek(word_list) == "verb":
        return match(word_list, "verb")
    raise ParserError("Expected a verb.")


def parse_object(word_list):
    skip(word_list, "stop")
    if peek(word_list) in ("noun", "direction"):
        return match(word_list, peek(word_list))
    raise ParserError("Expected a noun or direction.")


def parse_subject(word_list):
    skip(word_list, "stop")
    if peek(word_list) == "noun":
        return match(word_list, "noun")
    if peek(word_list) == "verb":
        return ("noun", "player")
    raise ParserError("Expected a subject.")


def parse_sentence(word_list):
    subj = parse_subject(word_list)
    verb = parse_verb(word_list)
    obj = parse_object(word_list)
    return (subj[1], verb[1], obj[1])


words = [("noun", "bear"), ("verb", "eat"), ("stop", "the"), ("noun", "princess")]
print("tokens:", words)
print("sentence:", parse_sentence(words))
